using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;

namespace Warehouse.Tests;

[TestClass]
public class ApiTests
{
    private sealed class Factory : WebApplicationFactory<Program>
    {
        public string Db = Path.Combine(Path.GetTempPath(), $"wh-{Guid.NewGuid():N}.db");
        protected override void ConfigureWebHost(IWebHostBuilder b)
        {
            b.UseSetting("ConnectionStrings:Warehouse", $"Data Source={Db}");
        }
        protected override void Dispose(bool disposing)
        {
            base.Dispose(disposing);
            Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();
            try { File.Delete(Db); } catch { }
        }
    }

    private static async Task<JsonElement> Json(HttpResponseMessage r) =>
        (await r.Content.ReadFromJsonAsync<JsonElement>());

    private static async Task<string> NewSupplier(HttpClient c, string name = "Acme")
    {
        var r = await c.PostAsJsonAsync("/suppliers", new { name, email = "a@b.c" });
        Assert.AreEqual(HttpStatusCode.Created, r.StatusCode);
        return (await Json(r)).GetProperty("id").GetString()!;
    }

    private static object Prod(string sup, string sku = "S1", int stock = 5, int level = 3, int status = 0) =>
        new { sku, name = "Widget", stock, reorderLevel = level, status, supplierId = sup };

    [TestMethod]
    public async Task SupplierRoundTrip()
    {
        using var f = new Factory(); var c = f.CreateClient();
        var id = await NewSupplier(c);
        var p = await c.PostAsJsonAsync("/products", Prod(id));
        Assert.AreEqual(HttpStatusCode.Created, p.StatusCode);
        var s = await Json(await c.GetAsync($"/suppliers/{id}"));
        Assert.AreEqual(1, s.GetProperty("products").GetArrayLength());
        var u = await c.PutAsJsonAsync($"/suppliers/{id}", new { name = "New" });
        Assert.AreEqual(HttpStatusCode.OK, u.StatusCode);
        Assert.AreEqual("New", (await Json(u)).GetProperty("name").GetString());
        Assert.AreEqual(1, (await Json(await c.GetAsync("/suppliers"))).GetArrayLength());
        Assert.AreEqual(HttpStatusCode.NotFound, (await c.GetAsync($"/suppliers/{Guid.NewGuid()}")).StatusCode);
    }

    [TestMethod]
    public async Task ProductRoundTripAndDelete()
    {
        using var f = new Factory(); var c = f.CreateClient();
        var sid = await NewSupplier(c);
        var r = await c.PostAsJsonAsync("/products", Prod(sid));
        var o = await Json(r);
        var id = o.GetProperty("id").GetString();
        Assert.AreEqual(sid, o.GetProperty("supplierId").GetString());
        Assert.AreEqual(0, o.GetProperty("status").GetInt32());
        var u = await c.PutAsJsonAsync($"/products/{id}", Prod(sid, "S1", 9, 3, 1));
        Assert.AreEqual(HttpStatusCode.OK, u.StatusCode);
        Assert.AreEqual(1, (await Json(u)).GetProperty("status").GetInt32());
        Assert.AreEqual(HttpStatusCode.NoContent, (await c.DeleteAsync($"/products/{id}")).StatusCode);
        Assert.AreEqual(HttpStatusCode.NotFound, (await c.GetAsync($"/products/{id}")).StatusCode);
    }

    [TestMethod]
    [DataRow(5, 3, 0, false)]
    [DataRow(3, 3, 0, true)]
    [DataRow(0, 3, 0, true)]
    [DataRow(0, 3, 1, false)]
    public async Task NeedsReorder(int stock, int level, int status, bool expected)
    {
        using var f = new Factory(); var c = f.CreateClient();
        var sid = await NewSupplier(c);
        var o = await Json(await c.PostAsJsonAsync("/products", Prod(sid, "X", stock, level, status)));
        Assert.AreEqual(expected, o.GetProperty("needsReorder").GetBoolean());
    }

    [TestMethod]
    public async Task Validation()
    {
        using var f = new Factory(); var c = f.CreateClient();
        var sid = await NewSupplier(c);
        foreach (var body in new[]
        {
            Prod(sid, stock: -1), Prod(sid, level: -1), Prod(sid, status: 7),
            Prod(Guid.NewGuid().ToString()), Prod(sid, sku: new string('x', 21)), Prod(sid, sku: ""),
        })
            Assert.AreEqual(HttpStatusCode.BadRequest, (await c.PostAsJsonAsync("/products", body)).StatusCode);
        Assert.AreEqual(HttpStatusCode.BadRequest,
            (await c.PostAsJsonAsync("/suppliers", new { name = new string('x', 101) })).StatusCode);
    }

    [TestMethod]
    public async Task UniqueConflicts()
    {
        using var f = new Factory(); var c = f.CreateClient();
        var sid = await NewSupplier(c);
        Assert.AreEqual(HttpStatusCode.Conflict, (await c.PostAsJsonAsync("/suppliers", new { name = "Acme" })).StatusCode);
        await c.PostAsJsonAsync("/products", Prod(sid));
        Assert.AreEqual(HttpStatusCode.Conflict, (await c.PostAsJsonAsync("/products", Prod(sid))).StatusCode);
    }
}
